BEGIN;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-001', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '一运动质点在某瞬时位于矢径 $\\begin{array} { r l } { \\vec { r } } & { { } ( \\mathbf { x } , \\mathbf { y } ) } \\end{array}$ 的端点处,则其速度大小为', '["$\\\\frac { d r } { d t }$","$\\\\frac { d \\\\vec { r } } { d t }$","$\\\\frac { d \\\\vec { \\\\mathbf { \\\\nabla } } \\\\vec { r } \\\\| } { d t }$","$\\\\sqrt { \\\\left( \\\\frac { d x } { d t } \\\\right) ^ { 2 } + \\\\left( \\\\frac { d y } { d t } \\\\right) ^ { 2 } }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习一.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-002', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '下述关于质点运动描述的表达式正确的是（    ）', '["$|\\\\Delta \\\\vec{r}| = \\\\Delta r$","$\\\\left| \\\\frac{d\\\\vec{r}}{dt} \\\\right| = \\\\frac{dr}{dt}$","$\\\\left| \\\\frac{d\\\\vec{r}}{dt} \\\\right| \\\\neq \\\\frac{dr}{dt}$","$|d\\\\vec{r}| \\\\neq ds$"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '**选项 (A)**：$|\\Delta \\vec{r}|$ 是位移的大小（直线距离），$\\Delta r = r_2 - r_1$ 是位矢模的增量。除非质点做通过原点的直线运动，否则二者不等。❌

**选项 (B)**：$\\left| \\frac{d\\vec{r}}{dt} \\right| = |\\vec{v}|$ 是速度大小；$\\frac{dr}{dt}$ 是位矢模的变化率（径向速率）。例如匀速圆周运动中 $\\frac{dr}{dt}=0$，但 $|\\vec{v}| \\neq 0$。❌

**选项 (C)**：速度大小通常不等于径向速率，符合一般曲线运动规律。✅

**选项 (D)**：在微积分极限意义下，$dt \\to 0$ 时弧长无限接近弦长，故 $|d\\vec{r}| = ds$。❌', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习一.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-003', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '某质点作直线运动的运动学方程为 $x = 3 t - 5 t ^ { 3 } + 2$ ,则该质点作', '["匀加速直线运动,加速度沿x轴正方向","匀加速直线运动,加速度沿x轴负方向","变加速直线运动,加速度沿x轴正方向","变加速直线运动,加速度沿x轴负方向。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习一.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-004', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 0, '第 4 题', '一质点沿 $x$ 轴运动，其加速度 $a$ 与位置坐标 $x$ 的关系为 $a = 2 + 6x^2$（SI）。如果质点在原点处的速度为零，则质点在 $x=2\\text{m}$ 处的速度大小 $v$ 约为（    ）', '["$40\\\\text{m/s}$","$5\\\\text{m/s}$","$20\\\\text{m/s}$","$10\\\\text{m/s}$"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '本题属于质点运动学第二类问题，加速度是位置 $x$ 的函数。利用链式法则：

$$a = \\frac{dv}{dt} = \\frac{dv}{dx}\\frac{dx}{dt} = v\\frac{dv}{dx}$$

分离变量得 $v\\,dv = a\\,dx = (2+6x^2)\\,dx$。

代入初始条件 $x=0$ 时 $v=0$，$x=2$ 时速度为 $v$，两边积分：

$$\\int_0^v v\\,dv = \\int_0^2 (2+6x^2)\\,dx$$

$$\\frac{1}{2}v^2 = \\left[2x+2x^3\\right]_0^2 = 4+16 = 20$$

$$v = \\sqrt{40} \\approx 6.32\\text{m/s}$$

最接近 $5\\text{m/s}$，故选 **B**。', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习一.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-005', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 2, '第 5 题', '一质点沿 x方向运动,其加速度随时间变化关系为 $a { = } 3 { + } 2 t$ 如果初始时质点的速度 $\\nu _ { 0 }$ 为 $5 \\mathrm { m / s }$ ,则当t为3s时,质点的速度v =', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习一.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-006', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 2, '第 6 题', '质点以加速度 $a { = } k t$ 作直线运动,式中 k为常数,设初速度为 $\\nu _ { 0 }$ ,求质点速度 v与时间t的函数关系', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习一.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-007', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 3, '第 7 题', '一质点在 xoy 平面上运动,运动方程为 $x { = } 3 t { + } 5$ $y = \\frac { 1 } { 2 } t ^ { 2 } + 3 t - 4$ 。求以下物理量并把它们表示成直角坐标系中的矢量形式。以时间t为变量,写出质点位置矢量的表示式;
(2)求出t=1s时刻和 $t { = } 2 \\mathbf { s }$ 时刻的位置矢量,计算这1秒内质点的位移;
(3)计算t=0s时刻到 $\\scriptstyle { t = 4 \\mathrm { s } }$ 时刻内的平均速度;
(4)求出质点速度矢量表示式,计算 $\\scriptstyle { t = 4 \\mathrm { s } }$ 时质点的速度;
(5)计算t=0s到t=4s内质点的平均加速度;
(6)求出质点加速度矢量的表示式,计算t=4s时质点的加速度。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '力学练习一.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-008', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 3, '第 8 题', '一质点沿 x 轴运动,其加速度为 $a { = } 4 t$ ,已知 $\\scriptstyle { t = 0 }$ 时,质点位于 ${ x } _ { 0 } \\mathrm { { = } } 1 0 \\mathrm { { m } }$ 处,初速度 $\\scriptstyle \\nu _ { 0 } = 0$ 。试求其位置和时间的关系式。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '力学练习一.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-009', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 3, '第 9 题', '一个质点沿 x 轴运动,其加速度和位置的关系为 $\\scriptstyle a = 2 + 6 x ^ { 2 }$ 。已知质点在 $x _ { 0 } { = } 0$ 处,速度为 $\\nu _ { 0 } { = } 1 0 m / s$ ,试求质点在任何坐标处的速度值。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '力学练习一.pdf 第9题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-001', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '下列说法中,哪一个是正确的？', '["一质点在某时刻的瞬时速度是2 m/s,说明它在此后1 s内一定要经过2 m的路程","斜向上抛的物体,在最高点处的速度最小,加速度最大","物体作曲线运动时,有可能在某时刻的法向加速度为零","物体加速度越大,则速度越大。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-002', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '质点作半径为 $R$ 的变速圆周运动时的加速度大小为（   ）（$v$ 表示任一时刻质点的速率）', '["$\\\\frac{dv}{dt}$","$\\\\frac{v^2}{R}$","$\\\\frac{v^2}{R} + \\\\frac{dv}{dt}$","$\\\\sqrt{\\\\left(\\\\frac{v^2}{R}\\\\right)^2 + \\\\left(\\\\frac{dv}{dt}\\\\right)^2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '变速圆周运动的加速度由两个互相垂直的分量组成：

- **切向加速度**：$a_t = \\frac{dv}{dt}$，改变速度大小。
- **法向加速度**：$a_n = \\frac{v^2}{R}$，改变速度方向。

加速度是矢量，需用勾股定理合成：

$$a = \\sqrt{a_n^2 + a_t^2} = \\sqrt{\\left(\\frac{v^2}{R}\\right)^2 + \\left(\\frac{dv}{dt}\\right)^2}$$

故选 **D**。

注意：匀速圆周运动时 $\\frac{dv}{dt}=0$，则 $a=\\frac{v^2}{R}$（对应选项 B）。', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-003', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '在一个转动的齿轮上,一个齿尖 P 沿半径为 R=0.2m 的圆周运动,其路程 S 随时间的变化规律为 $S = \\nu _ { 0 } t + { \\frac { 1 } { 2 } } b t ^ { 2 }$ ,其中 $\\nu _ { 0 } { = } 2 \\mathrm { m / s }$ 和 $b = 0 . 3 m / s ^ { 2 }$ 0则t=5s时齿尖P的总加速度大小a约等于', '["$3 4 \\\\mathrm { m } / \\\\mathrm { s } ^ { 2 }$","$4 2 \\\\mathrm { m } / \\\\mathrm { s } ^ { 2 }$","$5 1 \\\\mathrm { m } / \\\\mathrm { s } ^ { 2 }$","$6 1 \\\\mathrm { m } / \\\\mathrm { s } ^ { 2 }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-004', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 4 题', '质点的质量为 $m$，置于光滑球面的顶点 $A$ 处（球面固定不动），如图所示。当它由静止开始下滑到球面上 $B$ 点时（设 $OB$ 与竖直方向夹角为 $\\theta$），它的加速度的大小为（   ）', '["$a = g\\\\sqrt{1 - \\\\cos\\\\theta}$","$a = g\\\\sin\\\\theta$","$a = g$","$a = g\\\\sqrt{4\\\\sin^2\\\\theta + (1 - \\\\cos\\\\theta)^2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '质点在光滑球面上运动，只有重力做功，机械能守恒。下降高度 $h = R(1-\\cos\\theta)$，故：

$$mgR(1-\\cos\\theta) = \\frac{1}{2}mv^2$$

$$v^2 = 2gR(1-\\cos\\theta)$$

在自然坐标系下：

- **法向加速度**：$a_n = \\frac{v^2}{R} = 2g(1-\\cos\\theta)$
- **切向加速度**：$a_t = g\\sin\\theta$

总加速度大小为：

$$a = \\sqrt{a_n^2 + a_t^2} = g\\sqrt{4(1-\\cos\\theta)^2 + \\sin^2\\theta}$$

故选 **D**。', NULL, NULL, '/physics/training/p1b-m1-02-training/d9ee40d816856f6b75588d5c5adde7fbe6076a36381795ded5d2220b3ba1b1f9.jpg', 1, '["选择题"]'::jsonb, '力学练习二.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
