INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-010', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 3, '第 10 题', '由楼窗口以水平初速度 $\\overrightarrow { \\nu _ { 0 } }$ 射出一发子弹,射出时子弹离地面的高度为 h,取枪口为原点,沿 $\\overrightarrow { \\nu _ { 0 } }$ 方向为 x轴,竖直向下为 y轴,并取发射时刻t为0,试求：子弹在任一时刻 的位置坐标及轨迹方程;
(2)子弹在t时刻的速度,切向加速度和法向加速度;
(3)子弹轨道落地处的曲率半径。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '力学练习二.pdf 第10题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-03-training-001', 'p1b-m1-03-training', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '在足够长的管中装有粘滞液体，放入钢球由静止开始向下运动，下列说法中正确的是：（    ）', '["钢球运动越来越慢，最后静止不动","钢球运动越来越慢，最后达到稳定的速度","钢球运动越来越快，一直无限制地增加","钢球运动越来越快，最后达到稳定的速度"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '钢球在粘滞液体中向下运动时，受三个力：竖直向下的重力 $G$、竖直向上的浮力 $F_{浮}$ 和竖直向上的粘滞阻力 $f$。粘滞阻力 $f$ 随速度增大而增大。

1. **初始状态**：$v=0$，$f=0$，因钢球密度大于液体，$G > F_{浮}$，合力向下，钢球开始向下加速。
2. **加速过程**：随着 $v$ 增大，$f$ 增大，向下的合力 $F_{合}=G-F_{浮}-f$ 逐渐减小，加速度 $a$ 逐渐减小。但只要 $F_{合}>0$，速度仍在增大。
3. **最终状态**：当 $G = F_{浮}+f$ 时，$F_{合}=0$，$a=0$，钢球以此时的速度向下做匀速直线运动，即达到**收尾速度（Terminal Velocity）**。

因此钢球运动越来越快，最后达到稳定的速度。故选 **D**。', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习三.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-03-training-002', 'p1b-m1-03-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '质量分别为 $m$ 和 $M$ 的滑块 $A$ 和 $B$，叠放在光滑水平桌面上，如图所示。$A$、$B$ 间静摩擦系数为 $\\mu_s$，滑动摩擦系数为 $\\mu_k$，系统原处于静止。今有一水平力作用于 $A$ 上，要使 $A$、$B$ 不发生相对滑动，则应有（    ）', '["$F \\\\leq \\\\mu_s mg$","$F \\\\leq \\\\mu_s (1 + m/M)mg$","$F \\\\leq \\\\mu_s (m+M)mg$","$F \\\\leq \\\\mu_s mg \\\\frac{m}{M}$"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '要使 $A$、$B$ 不发生相对滑动，两者必须保持相对静止，即具有相同加速度。此时 $A$、$B$ 之间的摩擦力为静摩擦力。

**整体法**：将 $A$、$B$ 看作整体，总质量为 $(M+m)$，只受水平拉力 $F$：

$$F = (M+m)a$$

**隔离法**：单独分析滑块 $B$，水平方向只受 $A$ 对 $B$ 的静摩擦力 $f$：

$$f = Ma$$

临界条件为静摩擦力达到最大静摩擦力：

$$f_{max} = \\mu_s N_A = \\mu_s mg$$

（$N_A$ 是 $A$ 对 $B$ 的压力，大小等于 $A$ 的重力 $mg$）

由隔离法得系统最大加速度：

$$Ma_{max} = \\mu_s mg \\Rightarrow a_{max} = \\frac{\\mu_s mg}{M}$$

代入整体法：

$$F_{max} = (M+m)a_{max} = (M+m)\\cdot\\frac{\\mu_s mg}{M} = \\mu_s mg\\left(1+\\frac{m}{M}\\right)$$

故选 **B**。', NULL, NULL, '/physics/training/p1b-m1-03-training/fa05c9f7443c261e509c0a00757428cdfaeed2a7f62dc8b730aba305f38e990b.jpg', 1, '["选择题"]'::jsonb, '力学练习三.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-03-training-003', 'p1b-m1-03-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '质量为m的物体最初位于 $x _ { 0 }$ 处,在力 $F = - k / x ^ { 2 }$ 作用下由静止开始沿直线运动,k为一常数,则物体在任一位置x处的速度应为', '["$\\\\sqrt { \\\\frac { k } { m } ( \\\\frac { 1 } { x } - \\\\frac { 1 } { x _ { 0 } } ) }$","$\\\\sqrt { \\\\frac { 2 k } { m } ( \\\\frac { 1 } { x } - \\\\frac { 1 } { x _ { 0 } } ) }$","$\\\\sqrt { \\\\frac { 3 k } { m } ( \\\\frac { 1 } { x } - \\\\frac { 1 } { x _ { 0 } } ) }$","$\\\\sqrt { { \\\\frac { 4 k } { m } } ( { \\\\frac { 1 } { x } } - { \\\\frac { 1 } { x _ { 0 } } } ) }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习三.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-03-training-004', 'p1b-m1-03-training', 'physics-b-1', 'p1b-m1', 2, '第 4 题', '( tk1000A000010957)已知一质量为m 的质点在x 轴上运动,质点只受到指向原点的引力的作用,引力大小与质点离原点的距离x的平方成反比,即$f = - k / x ^ { 2 }$ ,k 是比例常数。设质点在 $x = 8 . 0 0 m$ 时的速度为零,则质点在$x = 2 . 0 0 m$ 处的速率v= o', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习三.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
