INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-04-training-002', 'p1b-m1-04-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '如图所示,流水以初速度 $\\nu _ { 1 }$ 进入弯管,流出时的速度为$\\nu _ { 2 }$ ,且 $\\nu _ { 1 } = \\nu _ { 2 } = 5 . 0 ~ \\mathrm { m / s } ,$ ,设每秒流入的水质量为 $q = 1 0 ~ \\mathrm { k g / s }$ ,则在管子转弯处,水对管壁的平均冲力F 大小为', '["50 N","100 N;30°","150 N","200 N。A"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-04-training/122af3b51e98d071b7fb8105bb19d2d8969807ece3ed8d762b298ce2006fd3ca.jpg', 1, '["选择题"]'::jsonb, '力学练习四.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-04-training-003', 'p1b-m1-04-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '设作用在质量为 $m { = } 2 . 0 0 \\mathrm { k g }$ 的物体上的力 $F { = } 6 . 0 0 t { + } 3 . 0 0$ (SI)。如果物体在这一力的作用下, 由静止开始沿直线运动,在0到1.50s的时间间隔内,这个力作用在物体上的冲量大小I=', '["$1 1 \\\\mathrm { N } . \\\\mathrm { s } ;$","18Ns","36Ns","60Ns"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习四.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
